const html = $('Fetch Career Page HTML').item.json.data || '';
const source = $('Preserve Source Metadata').item.json;
const companyId = source.company_id;
const sourceId = source.source_id;
const sourceUrl = source.source_url;

const extractedJobs = [];

// 1. JSON-LD parsing
const jsonLdRegex = /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
let match;
while ((match = jsonLdRegex.exec(html)) !== null) {
  try {
    const rawJson = match[1].trim();
    const data = JSON.parse(rawJson);

    const processObject = (obj) => {
      if (obj && (obj['@type'] === 'JobPosting' || obj['type'] === 'JobPosting')) {
        const title = obj.title || obj.name;
        const description = obj.description || '';
        let location = '';
        if (obj.jobLocation) {
          if (typeof obj.jobLocation === 'string') {
            location = obj.jobLocation;
          } else if (obj.jobLocation.address) {
            const addr = obj.jobLocation.address;
            location = [addr.streetAddress, addr.addressLocality, addr.addressRegion, addr.postalCode, addr.addressCountry]
              .filter(Boolean)
              .join(', ');
          }
        }
        const appUrl = obj.url || sourceUrl;

        if (title) {
          extractedJobs.push({
            company_id: companyId,
            source_id: sourceId,
            title: title.trim(),
            description: description.trim() || `Open position for ${title.trim()}. See details at ${sourceUrl}`,
            location: location.trim() || 'Remote / Unspecified',
            job_type: "Full-time",
            remote_type: location.toLowerCase().includes('remote') ? 'remote' : 'hybrid',
            currency: "USD",
            application_url: appUrl.trim(),
            is_valid: true
          });
        }
      }
    };

    if (Array.isArray(data)) {
      data.forEach(processObject);
    } else if (data['@graph'] && Array.isArray(data['@graph'])) {
      data['@graph'].forEach(processObject);
    } else {
      processObject(data);
    }
  } catch (e) {
    // Ignore invalid JSON-LD blocks
  }
}

// 2. HTML parsing fallback
if (extractedJobs.length === 0) {
  const blockRegex = /<(div|li|article|section)\b[^>]*class=["'][^"']*(?:job|vacancy|position|posting|listing|opportunity|career)[^"']*["'][^>]*>([\s\S]*?)<\/\1>/gi;

  let blockMatch;
  while ((blockMatch = blockRegex.exec(html)) !== null) {
    const blockContent = blockMatch[2];

    let title = '';
    const hRegex = /<h[1-4]\b[^>]*>([\s\S]*?)<\/h[1-4]>/i;
    const hMatch = hRegex.exec(blockContent);
    if (hMatch) {
      title = hMatch[1].replace(/<[^>]*>/g, '').trim();
    } else {
      const classTitleRegex = /<[^>]*class=["'][^"']*(?:title|position|role|job-name)[^"']*["'][^>]*>([\s\S]*?)<\/[^>]+>/i;
      const classTitleMatch = classTitleRegex.exec(blockContent);
      if (classTitleMatch) {
        title = classTitleMatch[1].replace(/<[^>]*>/g, '').trim();
      }
    }

    let location = '';
    const locRegex = /<[^>]*class=["'][^"']*(?:location|city|remote|country|place|region)[^"']*["'][^>]*>([\s\S]*?)<\/[^>]+>/i;
    const locMatch = locRegex.exec(blockContent);
    if (locMatch) {
      location = locMatch[1].replace(/<[^>]*>/g, '').trim();
    }

    let description = '';
    const descRegex = /<[^>]*class=["'][^"']*(?:desc|summary|detail|content|body)[^"']*["'][^>]*>([\s\S]*?)<\/[^>]+>/i;
    const descMatch = descRegex.exec(blockContent);
    if (descMatch) {
      description = descMatch[1].replace(/<[^>]*>/g, '').trim();
    }

    let appUrl = '';
    const linkRegex = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    let linkMatch;
    let bestLink = '';
    while ((linkMatch = linkRegex.exec(blockContent)) !== null) {
      const href = linkMatch[1];
      const text = linkMatch[2].replace(/<[^>]*>/g, '').toLowerCase();
      if (text.includes('apply') || text.includes('view') || text.includes('detail') || href.includes('job') || href.includes('apply')) {
        bestLink = href;
        break;
      }
      if (!bestLink) {
        bestLink = href;
      }
    }

    if (bestLink) {
      if (bestLink.startsWith('/')) {
        try {
          const urlObj = new URL(sourceUrl);
          appUrl = urlObj.origin + bestLink;
        } catch (e) {
          appUrl = sourceUrl;
        }
      } else if (!bestLink.startsWith('http')) {
        appUrl = sourceUrl;
      } else {
        appUrl = bestLink;
      }
    } else {
      appUrl = sourceUrl;
    }

    if (title && title.length > 2 && title.length < 150) {
      extractedJobs.push({
        company_id: companyId,
        source_id: sourceId,
        title: title,
        location: location || 'Remote / Unspecified',
        description: description || `Open position for ${title}. See details at ${sourceUrl}`,
        job_type: "Full-time",
        remote_type: (location.toLowerCase().includes('remote') || title.toLowerCase().includes('remote')) ? 'remote' : 'hybrid',
        currency: "USD",
        application_url: appUrl,
        is_valid: true
      });
    }
  }
}

// 3. Output check
if (extractedJobs.length === 0) {
  return [{
    json: {
      company_id: companyId,
      source_id: sourceId,
      source_url: sourceUrl,
      is_valid: false,
      status: "no_jobs_extracted",
      reason: "Could not parse any jobs from the career page"
    }
  }];
}

return extractedJobs.map(job => ({ json: job }));
